#!/usr/bin/env bash
set -e

echo "삼치기 Hedge V3.1 표본보호 업데이트 중..."

if [ ! -f "app/src/main/java/com/bubbleladder/triplehedgev3/TripleCore.java" ]; then
  echo "오류: 기존 V3 저장소에서 실행해야 합니다."
  echo "패키지 com.bubbleladder.triplehedgev3 프로젝트를 확인하세요."
  exit 1
fi

mkdir -p ".github/workflows" "app/src/main/java/com/bubbleladder/triplehedgev3"

echo "" | base64 -d > ".github/workflows/build-apk.yml"

echo "" | base64 -d > "app/build.gradle"

echo "" | base64 -d > "app/src/main/java/com/bubbleladder/triplehedgev3/TripleCore.java"

echo "" | base64 -d > "app/src/main/java/com/bubbleladder/triplehedgev3/MainActivity.java"

echo "" | base64 -d > "app/src/main/java/com/bubbleladder/triplehedgev3/AutoDrawService.java"

echo "" | base64 -d > "README.md"

git add .
git commit -m "V3.1 sample guard - small context sample protection" || true
git push

echo "완료!"
echo "Actions > Build Android APK > BubbleTripleHedgeV3-4Probability-debug-apk"
echo "기존 V3 앱 위에 app-debug.apk를 덮어쓰기 설치하세요."
